<script setup>
import { ref, watch } from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTag from '../../../components/mds/MTag.vue';
const props=defineProps({rows:{type:Array,default:()=>[]},total:Number,page:Number,pageSize:Number,search:String,category:String,sentiment:String,status:String,loading:Boolean});const emit=defineEmits(['back','search','filters','page']);const draftSearch=ref(props.search||'');watch(()=>props.search,(value)=>{draftSearch.value=value||'';});const categories=[{value:'',label:'Mọi phân loại'},{value:'brand',label:'Thương hiệu'},{value:'industry',label:'Tin ngành'},{value:'competitor',label:'Đối thủ'}];const sentiments=[{value:'',label:'Mọi sắc thái'},{value:'positive',label:'Tích cực'},{value:'neutral',label:'Trung tính'},{value:'negative',label:'Tiêu cực'}];const statuses=[{value:'',label:'Mọi trạng thái'},{value:'Mới',label:'Mới'},{value:'Đang xử lý',label:'Đang xử lý'},{value:'Đã xử lý',label:'Đã xử lý'}];function apply(key,value){emit('filters',{[key]:value});}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="flex items-start justify-between gap-3 rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><div><h1 class="text-[20px] font-semibold">Tin bài giám sát</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ total || 0 }} tin do máy chủ lọc và trả về. Cập nhật xử lý là bước review riêng.</p></div><MButton variant="neutral" @click="emit('back')">Tổng quan</MButton></header><div class="grid gap-2 rounded-lg bg-[var(--mds-bg)] p-4 shadow-[var(--mds-shadow-card)] md:grid-cols-4"><form class="md:col-span-2" @submit.prevent="emit('search',draftSearch)"><MInput v-model="draftSearch" placeholder="Tìm tiêu đề hoặc nguồn…"/></form><MSelect :model-value="category" :options="categories" @update:model-value="apply('category',$event)"/><MSelect :model-value="sentiment" :options="sentiments" @update:model-value="apply('sentiment',$event)"/><MSelect :model-value="status" :options="statuses" @update:model-value="apply('status',$event)"/></div><section class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><div v-if="rows.length" class="divide-y divide-[var(--mds-border-light)]"><article v-for="row in rows" :key="row.id" class="px-5 py-4"><div class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><a v-if="row.link" :href="row.link" target="_blank" rel="noopener noreferrer" class="font-semibold text-[var(--mds-brand-600)]">{{row.title}}</a><strong v-else>{{row.title}}</strong><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{row.sourceName||'—'}} · {{row.publishedAt||'—'}}</p></div><div class="flex gap-2"><MTag color="neutral">{{row.category||'—'}}</MTag><MTag :color="row.sentiment==='negative'?'danger':row.sentiment==='positive'?'success':'neutral'">{{row.sentiment||'—'}}</MTag></div></div><p v-if="row.summary" class="mt-2 text-[13px] leading-[18px]">{{row.summary}}</p><p class="mt-2 text-[12px] text-[var(--mds-text-secondary)]">{{row.status||'—'}}<span v-if="row.assignee"> · {{row.assignee}}</span></p></article></div><MEmptyState v-else title="Chưa có tin bài" description="Thử đổi bộ lọc hoặc chạy quét từ quy trình được phê duyệt."/></section><footer class="flex items-center justify-end gap-2"><span class="mr-auto text-[13px] text-[var(--mds-text-secondary)]">Trang {{page||1}}</span><MButton variant="neutral" :disabled="loading||page<=1" @click="emit('page',page-1)">Trước</MButton><MButton variant="neutral" :disabled="loading||page*pageSize>=total" @click="emit('page',page+1)">Sau</MButton></footer></div></section></template>
